const nodeExternals = require('webpack-node-externals');
const slsw = require('serverless-webpack');

module.exports = {
  entry: slsw.lib.entries,
  target: 'node',
  mode: slsw.lib.webpack.isLocal ? 'development' : 'production',
  externals: [nodeExternals()],
  module: {
    rules: [
      {
        test: /\.js$/,
        include: __dirname,
        exclude: /node_modules/,
        use: {
          loader: 'babel-loader',
        },
      },
    ],
  },
};

import Joi from 'joi';
import { ObjectID } from 'mongodb';
import { clientError, success, serverError } from './utils/responses';
import getParams from './utils/getParams';
import connectToDb from './utils/connectToDb';

export default (event, context, callback) => {
  const schema = {
    userId: Joi.string().required(),
    goal: Joi.object()
      .keys({
        name: Joi.string().required(),
        frequencyId: Joi.number()
          .integer()
          .min(1)
          .max(3)
          .required(),
      })
      .required(),
  };

  Joi.validate(getParams(event), schema, async (err, { userId, goal }) => {
    if (err) {
      callback(...clientError(err));
    } else {
      try {
        const client = await connectToDb();
        const collection = client.db().collection('users');
        const user = await collection.findOne({ id: userId });
        if (!user) {
          callback(
            ...clientError({
              details: [
                { message: `User could not be found with id ${userId}` },
              ],
            })
          );
          return;
        }
        await collection.updateOne(
          { id: userId },
          { $set: { goals: [...user.goals, { ...goal, id: ObjectID() }] } }
        );

        callback(...success({ success: true }));
      } catch (e) {
        callback(...serverError(e));
      }
    }
  });
};

import Joi from 'joi';
import assert from 'assert';
import {
  clientError,
  success,
  serverError,
  singleClientError,
} from './utils/responses';
import getParams from './utils/getParams';
import connectToDb from './utils/connectToDb';

export default (event, context, callback) => {
  const schema = {
    userId: Joi.string().required(),
    goalId: Joi.string().required(),
    name: Joi.string().required(),
    frequencyId: Joi.number()
      .integer()
      .min(1)
      .max(3)
      .required(),
  };

  Joi.validate(
    getParams(event),
    schema,
    async (err, { userId, goalId, name, frequencyId }) => {
      if (err) {
        callback(...clientError(err));
      } else {
        try {
          const client = await connectToDb();
          const collection = client.db().collection('users');
          const user = await collection.findOne({ id: userId });
          if (!user) {
            callback(
              ...singleClientError(`User could not be found with id ${userId}`)
            );
            client.close();
            return;
          }
          assert(user && user.goals && name && frequencyId);
          if (user.goals.findIndex(({ id }) => `${id}` === goalId) === -1) {
            callback(
              ...singleClientError(
                `Goal with id ${goalId} could not be found on user ${userId}`
              )
            );
            client.close();
            return;
          }
          await collection.updateOne(
            { id: userId },
            {
              $set: {
                goals: user.goals.map(oldGoal => {
                  if (`${oldGoal.id}` !== goalId) return oldGoal;
                  return { ...oldGoal, name, frequencyId };
                }),
              },
            }
          );
          callback(...success({ success: true }));
        } catch (e) {
          callback(...serverError(e));
        }
      }
    }
  );
};

import Joi from 'joi';
import { ObjectID } from 'mongodb';
import { clientError, success, serverError } from './utils/responses';
import getParams from './utils/getParams';
import connectToDb from './utils/connectToDb';

const defaultUser = params => ({
  goals: [],
  events: [],
  ...params,
});

export default (event, context, callback) => {
  const schema = {
    email: Joi.string()
      .email()
      .required(),
    id: Joi.string().required(),
  };

  Joi.validate(getParams(event), schema, (validationError, body) => {
    if (validationError) {
      callback(...clientError(validationError));
    } else {
      connectToDb()
        .then(client => {
          const db = client.db();
          const users = db.collection('users');
          const id = ObjectID();
          users.insertOne(defaultUser({ ...body, id }), insertError => {
            if (insertError) {
              callback(...serverError(insertError));
            } else {
              callback(...success({ userId: id, success: true }));
            }
            client.close();
          });
        })
        .catch(connectionError => {
          callback(connectionError);
        });
    }
  });
};

import Joi from 'joi';
import { ObjectID } from 'mongodb';
import {
  clientError,
  success,
  serverError,
  singleClientError,
} from './utils/responses';
import getParams from './utils/getParams';
import connectToDb from './utils/connectToDb';

export default (event, context, callback) => {
  const eventArraySchema = Joi.array()
    .items(
      Joi.object().keys({
        date: Joi.string()
          .regex(
            /^([12]\d{3}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01]))$/,
            `YYYY-MM-DD`
          )
          .required(),
        goalId: Joi.string().required(),
      })
    )
    .required();
  const schema = {
    userId: Joi.string().required(),
    eventsToAdd: eventArraySchema,
    eventIdsToRemove: Joi.array()
      .items(Joi.string())
      .required(),
  };

  Joi.validate(
    getParams(event),
    schema,
    async (err, { userId, eventsToAdd = [], eventIdsToRemove = [] }) => {
      if (err) {
        callback(...clientError(err));
      } else {
        try {
          const client = await connectToDb();
          const users = client.db().collection('users');
          const user = await users.findOne({ id: userId });
          if (!user) {
            callback(...singleClientError(`Could not find user`));
            client.close();
            return;
          }

          if (!user.goals || user.goals.length === 0) {
            callback(...singleClientError(`User has no goals configured`));
            client.close();
            return;
          }

          const goalIds = user.goals.map(({ id }) => `${id}`);

          const errors = eventsToAdd.filter(
            ({ goalId }) => !goalIds.includes(goalId)
          );

          if (errors.length > 0) {
            callback(
              ...singleClientError(
                `Goal id ${errors[0].goalId} does not exist on this user`
              )
            );
            client.close();
            return;
          }

          const newEvents = [
            ...user.events,
            ...eventsToAdd.map(eventToAdd => ({
              ...eventToAdd,
              id: ObjectID(),
            })),
          ];

          const update = await users.updateOne(
            { id: userId },
            {
              $set: {
                events: newEvents.filter(
                  ({ id, goalId }) =>
                    id &&
                    !eventIdsToRemove.includes(`${id}`) &&
                    goalIds.includes(goalId)
                ),
              },
            }
          );

          if (update.result.ok !== 1) {
            callback(...serverError());
            return;
          }

          callback(...success({ success: true }));
        } catch (e) {
          callback(...serverError(e));
        }
      }
    }
  );
};

