import Joi from 'joi';
import assert from 'assert';
import {
  clientError,
  success,
  serverError,
  singleClientError,
} from './utils/responses';
import getParams from './utils/getParams';
import connectToDb from './utils/connectToDb';

export default (event, context, callback) => {
  const schema = {
    goalId: Joi.string().required(),
    userId: Joi.string().required(),
  };

  Joi.validate(getParams(event), schema, async (err, { userId, goalId }) => {
    if (err) {
      callback(...clientError(err));
    } else {
      try {
        const client = await connectToDb();
        const collection = client.db().collection('users');
        const user = await collection.findOne({ id: userId });
        if (!user) {
          callback(
            ...singleClientError(`User could not be found with id ${userId}`)
          );
          client.close();
          return;
        }
        assert(user && user.goals && goalId);
        if (user.goals.findIndex(({ id }) => `${id}` === goalId) === -1) {
          callback(
            ...singleClientError(
              `Goal with id ${goalId} could not be found on user ${userId}`
            )
          );
          client.close();
          return;
        }
        await collection.updateOne(
          { id: userId },
          {
            $set: {
              goals: user.goals.filter(
                oldGoal => oldGoal.id && `${oldGoal.id}` !== goalId
              ),
            },
          }
        );
        callback(...success({ success: true }));
      } catch (e) {
        callback(...serverError(e));
      }
    }
  });
};

export const clientError = err => [
  null,
  {
    statusCode: 400,
    body: JSON.stringify({
      errors: err.details,
    }),
  },
];
export const singleClientError = err => [
  null,
  {
    statusCode: 400,
    body: JSON.stringify({
      errors: [
        {
          message: err,
        },
      ],
    }),
  },
];

export const success = body => [
  null,
  {
    statusCode: 200,
    body: JSON.stringify(body),
  },
];

export const serverError = err => [
  err,
  {
    statusCode: 500,
    body: JSON.stringify(err),
  },
];

export default ({
  queryStringParameters = {},
  pathParameters = {},
  body = '{}',
}) => ({
  ...queryStringParameters,
  ...pathParameters,
  ...(body ? JSON.parse(body) : {}),
});

import { MongoClient } from 'mongodb';
import { user, password, suffix } from '../../secrets.json';

const url = `mongodb://${user}:${password}${suffix}`;

export default () =>
  new Promise((resolve, reject) => {
    MongoClient.connect(
      url,
      async (err, client) => {
        if (err) {
          reject(err);
        } else {
          resolve(client);
        }
      }
    );
  });
